describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    realmId: 'test-realm',
    accessToken: 'test-token',
    customerEmailToId: { 'jennyrosen@example.com': '123' },
    customFieldDefinitionId: '1',
  };

  it('creates invoice with correct field mapping and auth', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) {
        expect(req.headers.get('authorization')).toBe('Bearer test-token');
        expect(req.json).toMatchObject({
          DocNumber: 'in_1MtHbELkdIwHu7ixl4OzzPMv',
          CustomerRef: { value: '123', name: 'jennyrosen@example.com' },
          Line: [
            {
              Description: 'Consulting services',
              Amount: 100,
              DetailType: 'SalesItemLineDetail',
              SalesItemLineDetail: { Qty: 2, UnitPrice: 50 },
            },
            {
              Description: 'Software license',
              Amount: 50,
              DetailType: 'SalesItemLineDetail',
              SalesItemLineDetail: { Qty: 1, UnitPrice: 50 },
            },
          ],
          CustomField: [{ DefinitionId: '1', StringValue: 'https://pay.stripe.com/invoice/in_1MtHbELkdIwHu7ixl4OzzPMv' }],
        });
        return jsonResponse({ Invoice: { Id: '456', DocNumber: 'in_1MtHbELkdIwHu7ixl4OzzPMv', TxnDate: '2024-06-01', Balance: 150 } }, 201);
      }
      if (req.url.endsWith('/attachment')) {
        expect(req.headers.get('authorization')).toBe('Bearer test-token');
        expect(req.json).toMatchObject({
          AttachableRef: [{ EntityRef: { type: 'Invoice', value: '456' } }],
          FileName: 'stripe-invoice.pdf',
          ContentType: 'application/pdf',
        });
        expect(typeof req.json?.Body).toBe('string');
        return jsonResponse({ Attachment: { Id: '789', FileName: 'stripe-invoice.pdf', ContentType: 'application/pdf' } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(SOURCE_EXAMPLE as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch });
    expect(result.invoiceId).toBe('456');
    expect(result.attachmentId).toBe('789');
    expect(calls.length).toBe(2);
  });

  it('defaults quantity to 1 when missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      lines: {
        data: [
          { description: 'Item A', amount: 2000 }, // no quantity
          { description: 'Item B', amount: 3000, quantity: 3 },
        ],
      },
    };

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) {
        const lines = (req.json as any).Line;
        expect(lines[0].SalesItemLineDetail.Qty).toBe(1);
        expect(lines[0].SalesItemLineDetail.UnitPrice).toBe(20);
        expect(lines[1].SalesItemLineDetail.Qty).toBe(3);
        expect(lines[1].SalesItemLineDetail.UnitPrice).toBe(10);
        return jsonResponse({ Invoice: { Id: '456', DocNumber: 'in_1MtHbELkdIwHu7ixl4OzzPMv', TxnDate: '2024-06-01', Balance: 150 } }, 201);
      }
      if (req.url.endsWith('/attachment')) {
        return jsonResponse({ Attachment: { Id: '789', FileName: 'stripe-invoice.pdf', ContentType: 'application/pdf' } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    await handle(payload as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch });
    expect(calls.length).toBe(2);
  });

  it('throws on missing required field: hosted_invoice_url', async () => {
    const payload = { ...SOURCE_EXAMPLE, hosted_invoice_url: '' };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: hosted_invoice_url');
  });

  it('throws on missing customer mapping', async () => {
    const payload = { ...SOURCE_EXAMPLE, customer: { email: 'unknown@example.com' } };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch })).rejects.toThrow('No QuickBooks customer ID mapped for email: unknown@example.com');
  });

  it('throws on non-2xx response from create invoice', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    await expect(handle(SOURCE_EXAMPLE as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch })).rejects.toThrow('Create Invoice failed with 401:');
  });

  it('throws on non-2xx response from attachment', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/invoice')) {
        return jsonResponse({ Invoice: { Id: '456', DocNumber: 'in_1MtHbELkdIwHu7ixl4OzzPMv', TxnDate: '2024-06-01', Balance: 150 } }, 201);
      }
      if (req.url.endsWith('/attachment')) {
        return jsonResponse({ error: 'Forbidden' }, 403);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    await expect(handle(SOURCE_EXAMPLE as unknown as StripeInvoiceFinalizedPayload, { ...baseConfig, fetch })).rejects.toThrow('Attach Document failed with 403:');
    expect(calls.length).toBe(2); // both calls attempted
  });
});

